 public float Alt(Vector3 p){var a=Nearest(p);if(a==null)return 999;float distance=(p-a.body.P).magnitude,alt=distance-(float)a.body.radius;if(alt<a.body.atmosphere+a.body.radius*.15)alt-=Height(p-a.body.P,a.body.seed,a.body.radius);alt=SurfaceScatter.Current!=null?SurfaceScatter.Current.Altitude(p,alt):alt;return game!=null?game.CityAltitude(p,alt):alt;}
