  if(radius>100){lod=root.AddComponent<PlanetTerrainLOD>();lod.Initialize(body,mat);}else{var terrain=new GameObject("Spherical terrain / native matched surface");terrain.transform.SetParent(root.transform,false);terrain.AddComponent<MeshFilter>().sharedMesh=TerrainMesh(body,64);terrain.AddComponent<MeshRenderer>().sharedMaterial=mat;}
  var shell=GameObject.CreatePrimitive(PrimitiveType.Sphere);shell.name="Integrated atmosphere";shell.GetComponent<MeshFilter>().sharedMesh=ShellMesh();Destroy(shell.GetComponent<Collider>());shell.transform.SetParent(root.transform,false);float visualAirHeight=radius>100?radius*.20f:airHeight;shell.transform.localScale=Vector3.one*(radius+visualAirHeight)*2;var air=new Material(Shader.Find("Orbit/Atmosphere"));air.SetFloat("_GroundRadius",radius);air.SetFloat("_AtmosRadius",radius+visualAirHeight);air.SetVector("_PlanetCenter",p);air.SetColor("_Tint",SurfaceEcology.Climate(key)==SurfaceEcology.Biome.Arid?new Color(.48f,.32f,.18f):SurfaceEcology.Climate(key)==SurfaceEcology.Biome.Frozen?new Color(.30f,.48f,.65f):new Color(.26f,.40f,.48f));shell.GetComponent<Renderer>().sharedMaterial=air;shell.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
  if(radius>100){var clouds=GameObject.CreatePrimitive(PrimitiveType.Sphere);clouds.name="Weather / moving cloud layer";clouds.GetComponent<MeshFilter>().sharedMesh=ShellMesh();Destroy(clouds.GetComponent<Collider>());clouds.transform.SetParent(root.transform,false);clouds.transform.localScale=Vector3.one*(radius+radius*.16f)*2;var cm=new Material(Shader.Find("Orbit/Clouds"));cm.SetFloat("_Seed",(float)body.seed);cm.SetFloat("_Coverage",SurfaceEcology.Climate(key)==SurfaceEcology.Biome.Arid?.22f:SurfaceEcology.Climate(key)==SurfaceEcology.Biome.Frozen?.7f:1);clouds.GetComponent<Renderer>().sharedMaterial=cm;clouds.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}
