 public void Status(OrbitDemo.State ship){if(helmetTorch!=null)helmetTorch.enabled=OnFoot&&Vector3.Dot(crew.up,new Vector3(-.25f,.2f,-.94f).normalized)<.2f;Vector3 p=OnFoot?Focus:DefenseGame.Pos(ship),v=OnFoot?DefenseGame.Vel(foot):DefenseGame.Vel(ship);var a=Nearest(p);if(a==null){Altitude=999;Density=0;PlanetName="DEEP SPACE";NativeFallback=false;return;}float centerAltitude=Alt(p);Altitude=centerAltitude-(OnFoot?1.15f:game.RoverDeployed?.95f:.6f);VerticalSpeed=Vector3.Dot(v,(p-a.body.P).normalized);float airAltitude=a.body.radius>100?(p-a.body.P).magnitude-(float)a.body.radius:centerAltitude;float t=Mathf.Clamp01(((float)a.body.atmosphere-airAltitude)/Mathf.Max(2,(float)a.body.atmosphere*.2f));Density=airAltitude>=a.body.atmosphere?0:Mathf.Exp(-Mathf.Max(0,airAltitude)/((float)a.body.atmosphere*.3f))*t*t*(3-2*t);PlanetName=a.name;NativeFallback=InAtmosphere(p);
