 public string ToggleSurface(OrbitDemo.State ship){if(OnFoot){if(Vector3.Distance(Focus,DefenseGame.Pos(ship))>6)return "Return within 6u of your ship to reboard.";ResetCrew();return "Crew boarded. Raise the nose, throttle up and boost to climb.";}
