  Vector3 up=(DefenseGame.Pos(ship)-a.body.P).normalized,side=Vector3.Cross(up,game.ShipForward).normalized;if(side.sqrMagnitude<.1f)side=Vector3.right;Vector3 p=DefenseGame.Pos(ship)+side*(game.RoverDeployed?3.4f:2.5f)+up*.65f;if(game.RoverDeployed){p-=up*(Alt(p)-1.15f);if(SurfaceScatter.Current!=null)p=SurfaceScatter.Current.Clearance(p,1.15f);}crew.localScale=Vector3.one*1.3f;foreach(var b in buddies)b.localScale=Vector3.one*1.3f;crew.position=p;foot=new OrbitDemo.State{x=p.x,y=p.y,z=p.z};footHeading=SurfaceTangent(up,game.ShipForward);OnFoot=true;main.cullingMask|=1<<29;footYaw=0;footPitch=game.ModernSurface?8:14;
  for(int i=0;i<3;i++){Vector3 b=p+side*((i%2==0?1:-1)*(i+2)*1.4f);buddyStates[i]=new OrbitDemo.State{x=b.x,y=b.y,z=b.z};}
