 public static Vector3 SurfaceTangent(Vector3 up,Vector3 hint){Vector3 tangent=Vector3.ProjectOnPlane(hint,up);if(tangent.sqrMagnitude<.001f)tangent=Vector3.ProjectOnPlane(Mathf.Abs(up.y)<.9f?Vector3.up:Vector3.forward,up);return tangent.normalized;}
 public void InputTick(float dt){if(!OnFoot)return;var pad=game.Controls;bool keys=!GetComponent<HelmetPhotoUI>().AutomatedPlayback;System.Func<KeyCode,bool> key=k=>keys&&game.KeyHeld(k);float dx=keys?Input.GetAxisRaw("Mouse X")*2*game.MouseLookX:0,dy=keys?Input.GetAxisRaw("Mouse Y")*2*game.MouseLookY:0;
  footYaw+=dx+((key(KeyCode.RightArrow)?1:0)-(key(KeyCode.LeftArrow)?1:0))*60*dt+pad.Look.x*105*dt;
  if(keys&&game.KeyPressed(KeyCode.CapsLock)||pad.Down(PilotInput.Button.L3))RunToggle=!RunToggle;Sprinting=key(KeyCode.LeftShift)||key(KeyCode.RightShift)||RunToggle;
  footPitch=Mathf.Clamp(footPitch-dy+((key(KeyCode.DownArrow)?1:0)-(key(KeyCode.UpArrow)?1:0))*40*dt-pad.Look.y*80*dt,game.ModernSurface?-60:-12,65);
  var a=Nearest(Focus);Vector3 up=a==null?Vector3.up:(Focus-a.body.P).normalized,baseForward=SurfaceTangent(up,footHeading);footHeading=baseForward;Vector3 forward=Quaternion.AngleAxis(footYaw,up)*baseForward,right=Vector3.Cross(up,forward).normalized;
