  if((keys&&game.KeyPressed(KeyCode.Space)||pad.Down(PilotInput.Button.Cross))&&Altitude<.2f)jump=true;
 }
 public void SeatCrew(Transform vehicle,float deployment){if(OnFoot)return;main.cullingMask|=1<<29;var photos=GetComponent<HelmetPhotoUI>();for(int i=0;i<4;i++){var person=i==0?crew:buddies[i-1];person.gameObject.SetActive(true);person.localScale=Vector3.one*.90f;Vector3 local=new Vector3(i%2==0?-.53f:.53f,1.13f,i<2?.57f:-.82f);person.position=vehicle.TransformPoint(local);person.rotation=vehicle.rotation*Quaternion.Euler(0,180,0);if(i>0)photos.BindCompanion(person,i);var motion=i==0?Motion:buddyMotion[i-1];if(motion!=null)motion.SeatPose(i==0);}}
 public void FootStep(float dt){if(!OnFoot)return;Vector3 up=(Focus-Nearest(Focus).body.P).normalized,v=DefenseGame.Vel(foot),tangent=Vector3.ProjectOnPlane(v,up);Vector3 traction=Altitude<1.2f?Vector3.ClampMagnitude((footMove*(game.ModernSurface?(Sprinting?6.4f:2.35f):2.2f)-tangent)*(game.ModernSurface?10:6),game.ModernSurface?30:12):Vector3.zero;if(jump){v+=up*(game.ModernSurface?3.2f:1.5f);foot.vx=v.x;foot.vy=v.y;foot.vz=v.z;jump=false;bootRelease=.65f;}bootRelease=Mathf.Max(0,bootRelease-dt);if(Altitude<1.5f&&bootRelease<=0)traction-=up*2;StepMode(ref foot,traction,dt,2);crew.position=Focus;if(game.ModernSurface){Vector3 facing=Quaternion.AngleAxis(footYaw,up)*SurfaceTangent(up,footHeading);crew.rotation=Quaternion.Slerp(crew.rotation,Quaternion.LookRotation(-facing,up),1-Mathf.Exp(-14*dt));Motion.Pose(dt,DefenseGame.Vel(foot),Sprinting,this,Altitude<.25f&&bootRelease<=0);}else{Animate(crew,DefenseGame.Vel(foot).magnitude);if(footMove.sqrMagnitude>.1f)crew.rotation=Quaternion.Slerp(crew.rotation,Quaternion.LookRotation(-footMove.normalized,up),dt*12);else crew.rotation=Quaternion.LookRotation(SurfaceTangent(up,crew.forward),up);}
