 public void CameraClearance(){if(SurfaceScatter.Current!=null)main.transform.position=SurfaceScatter.Current.Clearance(main.transform.position,.3f);var a=Nearest(main.transform.position);if(a==null)return;Vector3 d=main.transform.position-a.body.P;float surface=(float)a.body.radius+Height(d,a.body.seed,a.body.radius)+.28f;if(d.magnitude<surface)main.transform.position=a.body.P+d.normalized*surface;}
 public void FootCamera(float dt){if(game.ModernSurface){var body=Nearest(Focus);Vector3 up0=(Focus-body.body.P).normalized,f=SurfaceTangent(up0,footHeading);footHeading=f;f=Quaternion.AngleAxis(footYaw,up0)*f;Vector3 side=Vector3.Cross(up0,f).normalized,aim=Quaternion.AngleAxis(footPitch,side)*f;bool aiming=game.CrewAim,running=Sprinting&&Speed>2;float range=aiming?3:running?6:5.4f;Vector3 goal0=Focus+up0*1.05f-aim*range+side*(aiming?.85f:running?1.6f:1.4f);main.transform.position=Vector3.Lerp(main.transform.position,goal0,1-Mathf.Exp(-14*dt));main.transform.rotation=Quaternion.Slerp(main.transform.rotation,Quaternion.LookRotation(aim,up0),1-Mathf.Exp(-16*dt));main.fieldOfView=Mathf.Lerp(main.fieldOfView,game.CameraFov(aiming?51:running?71:64),1-Mathf.Exp(-8*dt));return;}var a=Nearest(Focus);Vector3 up=(Focus-a.body.P).normalized,forward=SurfaceTangent(up,footHeading);footHeading=forward;forward=Quaternion.AngleAxis(footYaw,up)*forward;Vector3 behind=Quaternion.AngleAxis(footPitch,Vector3.Cross(up,forward))*-forward*5+up*1.5f;Vector3 goal=Focus+behind;main.transform.position=Vector3.Lerp(main.transform.position,goal,1-Mathf.Exp(-10*dt));main.transform.rotation=Quaternion.Slerp(main.transform.rotation,Quaternion.LookRotation(Focus+up*.65f-main.transform.position,up),1-Mathf.Exp(-10*dt));}
 static void Animate(Transform root,float speed){float amount=Mathf.Clamp01(speed/2);foreach(Transform part in root){float side=part.localPosition.x<0?-1:1,swing=Mathf.Sin(Time.time*7+side*Mathf.PI*.5f)*18*amount;if(part.name=="Boot")part.localRotation=Quaternion.Euler(swing,0,0);else if(part.name=="Glove and arm")part.localRotation=Quaternion.Euler(-swing*.7f,0,side*22);}}
 static Mesh shellMesh;static Mesh ShellMesh(){if(shellMesh!=null)return shellMesh;int n=64;var v=new List<Vector3>();var normals=new List<Vector3>();var tr=new List<int>();for(int face=0;face<6;face++){int start=v.Count;for(int y=0;y<=n;y++)for(int x=0;x<=n;x++){Vector3 d=PlanetTerrainLOD.Direction(face,2f*x/n-1,2f*y/n-1);v.Add(d*.5f);normals.Add(d);if(x<n&&y<n){int i=start+y*(n+1)+x;tr.AddRange(new[]{i,i+1,i+n+1,i+1,i+n+2,i+n+1});}}}shellMesh=new Mesh{name="Shared smooth cube-sphere shell / 64 subdivisions"};shellMesh.SetVertices(v);shellMesh.SetNormals(normals);shellMesh.SetTriangles(tr,0);shellMesh.RecalculateBounds();return shellMesh;}
 static Mesh TerrainMesh(Body body,int n){var verts=new List<Vector3>();var tris=new List<int>();Vector3[] normals={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};foreach(var normal in normals){Vector3 a=new Vector3(normal.y,normal.z,normal.x),b=Vector3.Cross(normal,a);int start=verts.Count;for(int y=0;y<=n;y++)for(int x=0;x<=n;x++){Vector3 dir=(normal+a*(2f*x/n-1)+b*(2f*y/n-1)).normalized;verts.Add(dir*((float)body.radius+Height(dir,body.seed,body.radius)));if(x<n&&y<n){int i=start+y*(n+1)+x;tris.AddRange(new[]{i,i+1,i+n+1,i+1,i+n+2,i+n+1});}}}var mesh=new Mesh();mesh.name="Deterministic cube-sphere terrain";mesh.SetVertices(verts);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
